def _is_relative_to(child: Path, parent: Path) -> bool:
    try:
        child.resolve().relative_to(parent.resolve())
        return True
    except (OSError, ValueError):
        return False


def _relative(path: Path) -> str:
    resolved = path.resolve()
    if not _is_relative_to(resolved, ROOT):
        raise ValueError("path escaped APP_ROOT: " + str(path))
    return str(resolved.relative_to(ROOT)).replace("\\", "/")


def _safe_directories(parent: Path) -> list[Path]:
    if not parent.exists() or not _is_relative_to(parent, ROOT):
        return []
    result: list[Path] = []
    for child in sorted(parent.iterdir(), key=lambda item: item.name.lower()):
        if child.is_symlink():
            continue
        if child.is_dir() and _is_relative_to(child, ROOT):
            result.append(child)
    return result


def _safe_files(parent: Path, suffixes: set[str] | None = None) -> list[Path]:
    if not parent.exists() or not _is_relative_to(parent, ROOT):
        return []
    allowed = suffixes or SAFE_TEXT_SUFFIXES
    result: list[Path] = []
    for child in sorted(parent.iterdir(), key=lambda item: item.name.lower()):
        if child.is_symlink() or not child.is_file():
            continue
        if child.suffix.lower() not in allowed:
            continue
        if _is_relative_to(child, ROOT):
            result.append(child)
    return result


def _bounded_files_in_known_tree(parent: Path, max_depth: int = 3) -> list[Path]:
    if not parent.exists() or not _is_relative_to(parent, ROOT):
        return []
    result: list[Path] = []
    stack: list[tuple[Path, int]] = [(parent, 0)]
    while stack:
        folder, depth = stack.pop()
        if depth > max_depth or folder.is_symlink() or not _is_relative_to(folder, ROOT):
            continue
        if any(part in SKIP_PARTS for part in folder.relative_to(ROOT).parts):
            continue
        for child in sorted(folder.iterdir(), key=lambda item: item.name.lower(), reverse=True):
            if child.is_symlink() or not _is_relative_to(child, ROOT):
                continue
            if child.is_dir():
                if depth < max_depth:
                    stack.append((child, depth + 1))
                continue
            if child.is_file() and child.suffix.lower() in SAFE_TEXT_SUFFIXES:
                result.append(child)
    return sorted(result, key=lambda item: _relative(item).lower())


def _limited(paths: Iterable[Path], limit: int = MAX_LISTED_PATHS) -> list[str]:
    return [_relative(path) for path in list(paths)[:limit]]


def _research_understanding_library_payload() -> dict[str, object]:
    path = ROOT / RESEARCH_UNDERSTANDING_LIBRARY_JSON
    if not path.exists() or not path.is_file() or not _is_relative_to(path, ROOT):
        return {"intent_families": []}
    try:
        payload = json.loads(path.read_text(encoding="utf-8", errors="replace"))
    except (OSError, json.JSONDecodeError):
        return {"intent_families": []}
    return payload if isinstance(payload, dict) else {"intent_families": []}


def _intent_families() -> list[dict[str, object]]:
    payload = _research_understanding_library_payload()
    families = payload.get("intent_families", [])
    if not isinstance(families, list):
        return []
    return [family for family in families if isinstance(family, dict)]


def _intent_domain_count(domain: str) -> int:
    return sum(1 for family in _intent_families() if family.get("domain") == domain)


def _conversation_command_supported_phrase_count() -> int:
    count = 0
    for family in _intent_families():
        phrases = family.get("phrases", [])
        if isinstance(phrases, list):
            count += len(phrases)
    return count


def _approved_library_materials_payload() -> dict[str, object]:
    path = ROOT / APPROVED_LIBRARY_MATERIALS_JSON
    if not path.exists() or not path.is_file() or not _is_relative_to(path, ROOT):
        return {"categories": []}
    try:
        payload = json.loads(path.read_text(encoding="utf-8", errors="replace"))
    except (OSError, json.JSONDecodeError):
        return {"categories": []}
    return payload if isinstance(payload, dict) else {"categories": []}


def _approved_library_categories() -> list[dict[str, object]]:
    categories = _approved_library_materials_payload().get("categories", [])
    if not isinstance(categories, list):
        return []
    return [category for category in categories if isinstance(category, dict)]


def _approved_library_material_counts() -> dict[str, int]:
    counts: dict[str, int] = {}
    for category in _approved_library_categories():
        slug = category.get("slug") or category.get("category") or category.get("category_slug")
        materials = category.get("approved_materials", [])
        if isinstance(slug, str) and isinstance(materials, list):
            counts[slug] = len(materials)
    return counts


def _approved_library_total_material_count() -> int:
    return sum(_approved_library_material_counts().values())


def _model_presence_status_string(role: str, display_name: str, statuses_by_role: dict[str, object]) -> str:
    status = statuses_by_role.get(role)
    presence = getattr(status, "status", "UNKNOWN / NOT_LOADED / NOT_RUNTIME")
    return f"{display_name} / {presence} / MANUAL_APPROVAL_REQUIRED"


def _external_root_manifest_status() -> str:
    manifest_paths = [
        Path(EXTERNAL_MEMORY_PRIMARY_SHELF) / "ENGEL_MEMORY_ROOT_MANIFEST.json",
        Path(EXTERNAL_MEMORY_SECONDARY_SHELF) / "ENGEL_MEMORY_ROOT_MANIFEST.json",
    ]
    present = 0
    for manifest_path in manifest_paths:
        try:
            if manifest_path.exists() and manifest_path.is_file():
                present += 1
        except OSError:
            continue
    if present == len(manifest_paths):
        return "PRESENT"
    if present:
        return "PARTIAL"
    return "MISSING"


